const d = JSON.parse(require('fs').readFileSync('/tmp/models.json','utf8')).data;
const rows = d.map((e) => { const b = e.benchmarks && e.benchmarks.artificial_analysis; return { id: e.id, iq: b ? b.intelligence_index : null, co: b ? b.coding_index : null, ag: b ? b.agentic_index : null }; });
const num = (v) => typeof v === 'number';
const all3 = rows.filter((r) => num(r.iq) && num(r.co) && num(r.ag));
const iqCo = rows.filter((r) => num(r.iq) && num(r.co));
const iqAg = rows.filter((r) => num(r.iq) && num(r.ag));
console.log('rows', rows.length, '| iq', rows.filter((r) => num(r.iq)).length, '| iq+co', iqCo.length, '| iq+ag', iqAg.length, '| all3', all3.length);
console.log('no iq but co and/or ag:', rows.filter((r) => !num(r.iq) && (num(r.co) || num(r.ag))).length, '| no iq and nothing:', rows.filter((r) => !num(r.iq) && !num(r.co) && !num(r.ag)).length);
function fit(list, xs) { // least squares y = c + sum a_i x_i via normal equations
  const n = list.length, k = xs.length + 1;
  const A = Array.from({ length: k }, () => new Array(k).fill(0)), B = new Array(k).fill(0);
  list.forEach((r) => { const v = [1].concat(xs.map((x) => r[x])); for (let i = 0; i < k; i++) { B[i] += v[i] * r.iq; for (let j = 0; j < k; j++) A[i][j] += v[i] * v[j]; } });
  for (let i = 0; i < k; i++) { let p = i; for (let r = i + 1; r < k; r++) if (Math.abs(A[r][i]) > Math.abs(A[p][i])) p = r; [A[i], A[p]] = [A[p], A[i]]; [B[i], B[p]] = [B[p], B[i]]; for (let r = i + 1; r < k; r++) { const f = A[r][i] / A[i][i]; for (let c = i; c < k; c++) A[r][c] -= f * A[i][c]; B[r] -= f * B[i]; } }
  const coef = new Array(k).fill(0); for (let i = k - 1; i >= 0; i--) { let s = B[i]; for (let j = i + 1; j < k; j++) s -= A[i][j] * coef[j]; coef[i] = s / A[i][i]; }
  const mean = list.reduce((s, r) => s + r.iq, 0) / n; let ssr = 0, sst = 0;
  list.forEach((r) => { const p = coef[0] + xs.reduce((s, x, i) => s + coef[i + 1] * r[x], 0); ssr += (r.iq - p) ** 2; sst += (r.iq - mean) ** 2; });
  return { coef: coef.map((c) => +c.toFixed(3)), r2: +(1 - ssr / sst).toFixed(3), rmse: +Math.sqrt(ssr / n).toFixed(2), n };
}
console.log('iq ~ co + ag  ', JSON.stringify(fit(all3, ['co', 'ag'])));
console.log('iq ~ co       ', JSON.stringify(fit(iqCo, ['co'])));
console.log('iq ~ ag       ', JSON.stringify(fit(iqAg, ['ag'])));
console.log('\nmodels with iq, co, ag:'); all3.slice(0, 40).forEach((r) => console.log(r.id.padEnd(46), 'iq', String(r.iq).padStart(5), 'co', String(r.co).padStart(5), 'ag', String(r.ag).padStart(5)));
console.log('\nmodels with iq but not both co/ag:'); rows.filter((r) => num(r.iq) && !(num(r.co) && num(r.ag))).slice(0, 12).forEach((r) => console.log(r.id.padEnd(46), 'iq', r.iq, 'co', r.co, 'ag', r.ag));
console.log('\nTWINS of Claude direct ids:'); ['anthropic/claude-opus-5.5','anthropic/claude-sonnet-5.5','anthropic/claude-haiku-5.5','anthropic/claude-fable-5.1','anthropic/claude-fable-5','anthropic/claude-opus-5'].forEach((id) => { const r = rows.find((x) => x.id === id); console.log(id.padEnd(34), r ? 'iq ' + r.iq + ' co ' + r.co + ' ag ' + r.ag : 'NOT IN THE LIST'); });
"

